<script setup>
import { computed,ref } from 'vue';import { Head,Link } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';import { createQuestions,isCorrect,score,shouldAutoCheck } from '../../lib/study.js';
const props=defineProps({collection:Object,words:{type:Array,default:()=>[]},mode:{type:String,default:'flashcards'},shared:{type:Boolean,default:false},settings:{type:Object,default:()=>({})}});
const options=ref({type:'choice',direction:'term',order:'random',count:Math.min(10,props.words.length),...props.settings});
const started=ref(false),questions=ref([]),index=ref(0),flipped=ref(false),answer=ref(''),checked=ref(false),correct=ref(false),results=ref([]),finished=ref(false),practiceRound=ref(false);
const current=computed(()=>questions.value[index.value]);
const summary=computed(()=>score(results.value));
const modeLabel=computed(()=>({flashcards:'Flashcards',study:'Study',test:'Test'}[props.mode]??'Study'));
const base=computed(()=>props.shared?`/s/${props.collection.share_uuid}`:`/collections/${props.collection.id}`);
const wrong=computed(()=>results.value.filter(r=>!r.correct));
function start(retry=false){const ids=new Set(wrong.value.map(r=>r.id));const source=retry?props.words.filter(w=>ids.has(w.id)):props.words;questions.value=createQuestions(source,{...options.value,count:retry?source.length:options.value.count});index.value=0;results.value=[];started.value=true;finished.value=false;practiceRound.value=retry;reset();}
function reset(){flipped.value=false;answer.value='';checked.value=false;correct.value=false;}
function check(){if(!answer.value.trim()||checked.value)return;correct.value=isCorrect(answer.value,current.value.expected);checked.value=true;if(props.mode==='test')next();}
function selectOption(value){if(checked.value)return;answer.value=value;if(shouldAutoCheck(props.mode,current.value.type))check();}
function next(mark=correct.value){if(!current.value)return;results.value.push({...current.value,answer:answer.value,correct:mark});if(index.value===questions.value.length-1){finished.value=true;return;}index.value++;reset();}
function restart(){started.value=false;finished.value=false;results.value=[];reset();}
</script>
<template><Head :title="`${modeLabel} · ${collection.title}`"/><AppLayout :title="modeLabel" :subtitle="collection.title" :shared="shared"><template #actions><Link :href="base" class="button secondary">← Collection</Link></template><div class="study-wrap"><section v-if="!words.length" class="panel empty"><h2>A few words first.</h2><p>This collection is empty. Add words before starting a session.</p><Link :href="base" class="button">Back to collection</Link></section><section v-else-if="!started" class="panel study-settings"><span class="step-label">MAKE IT YOURS</span><h2>How would you like to practice?</h2><p class="muted">{{mode==='flashcards'?'Turn each card over, then decide what needs another look.':mode==='test'?'Answer all questions, then review your results at the end.':'Get feedback as you go, then revisit the words that need more practice.'}}</p><form @submit.prevent="start()"><div class="two-col"><label>{{mode==='flashcards'?'Card front':'Question direction'}}<select v-model="options.direction"><option value="term">Show definition → recall word</option><option value="definition">Show word → recall definition</option></select></label><label v-if="mode!=='flashcards'">Answer style<select v-model="options.type"><option value="choice">Multiple choice</option><option value="written">Written answer</option></select></label><label>Order<select v-model="options.order"><option value="random">Shuffled</option><option value="ordered">Collection order</option></select></label><label>Number of {{mode==='flashcards'?'cards':'questions'}}<input v-model.number="options.count" type="number" min="1" :max="words.length" required/></label></div><p class="muted small" v-if="mode!=='flashcards'">Written answers ignore letter case and extra spaces, but keep accents and punctuation. During Study, you can mark an equivalent definition correct. Tests use exact normalized matching.</p><p class="muted small">Progress lasts for this session. {{shared?'No account is required, and results are not saved to the collection owner.':'Leaving or reloading this page starts a new session.'}}</p><div class="form-actions"><button class="button">Start {{modeLabel.toLowerCase()}} →</button></div></form></section><section v-else-if="finished" class="panel results"><span class="step-label">{{practiceRound?'ANOTHER STEP FORWARD':'SESSION COMPLETE'}}</span><div class="score-circle">{{summary.percent}}<small>%</small></div><h2>{{summary.percent===100?'Look at you grow.':'Every attempt is progress.'}}</h2><p class="muted">{{summary.correct}} of {{summary.total}} {{mode==='flashcards'?'cards marked known':'answers correct'}}.</p><div class="actions centered"><button v-if="wrong.length" class="button" @click="start(true)">Practice {{wrong.length}} again</button><button class="button secondary" @click="restart">New session</button></div><div class="review-list"><article v-for="(item,i) in results" :key="i" class="review-item"><span :class="item.correct?'result-good':'result-bad'">{{item.correct?'✓':'↻'}}</span><div><strong>{{item.prompt}}</strong><p>{{item.expected}}</p><small v-if="mode!=='flashcards'&&!item.correct">Your answer: {{item.answer || '(blank)'}}</small></div></article></div></section><template v-else-if="current"><div class="study-progress"><span>{{practiceRound?'Practice again':modeLabel}}</span><strong>{{index+1}} / {{questions.length}}</strong></div><div class="progress-track"><div :style="{width:`${index/questions.length*100}%`}"/></div><template v-if="mode==='flashcards'"><button class="flashcard" @click="flipped=!flipped" :aria-label="flipped?'Show question':'Reveal answer'"><span class="tiny-label">{{flipped?'THE ANSWER':current.answerKey==='term'?'THE DEFINITION':'THE WORD'}}</span><strong>{{flipped?current.expected:current.prompt}}</strong><p v-if="flipped&&!shared&&current.note" class="card-note">{{current.note}}</p><small>{{flipped?'↶ Tap to turn back':'↻ Tap to reveal'}}</small></button><div class="actions centered"><button class="button secondary" :disabled="!flipped" @click="next(false)">↻ Still learning</button><button class="button" :disabled="!flipped" @click="next(true)">✓ I know this</button></div></template><section v-else class="panel question-panel"><span class="tiny-label">{{current.answerKey==='term'?'WHICH WORD FITS?':'WHAT DOES THIS MEAN?'}}</span><h2>{{current.prompt}}</h2><form @submit.prevent="check"><div v-if="current.type==='choice'" class="answer-options"><label v-for="(option,i) in current.options" :key="option" :class="['answer-option',{selected:answer===option}] "><input type="radio" name="answer-choice" :checked="answer===option" :value="option" @change="selectOption(option)" :disabled="checked" required/><span class="option-letter">{{String.fromCharCode(65+i)}}</span><span>{{option}}</span></label></div><label v-else>Your answer<textarea v-model="answer" :disabled="checked" rows="3" required placeholder="Make room for recall…"/></label><p v-if="current.type==='written'&&options.type==='choice'" class="muted small">Not enough distinct options for this card, so try a written answer.</p><div v-if="checked" :class="['answer-feedback',correct?'good':'needs-practice']" role="status"><strong>{{correct?'✓ You got it.':'↻ One to remember.'}}</strong><p>{{current.expected}}</p><button v-if="!correct&&current.type==='written'&&current.answerKey==='definition'" type="button" class="text-button" @click="correct=true">My definition means the same thing</button></div><div class="form-actions"><button v-if="!checked && !shouldAutoCheck(mode,current.type)" class="button" :disabled="!answer.trim()">{{mode==='test'?'Submit answer →':'Check answer'}}</button><button v-else-if="checked" class="button" type="button" @click="next()">{{index===questions.length-1?'See results':'Next word →'}}</button></div></form></section></template></div></AppLayout></template>
